/* gaemiGTP: user-provided character and demo audio, embedded to avoid extra asset hosting. */
(function(){
  function asBlobUrl(base64,mime){
    const binary=atob(base64),bytes=new Uint8Array(binary.length);
    for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
    return URL.createObjectURL(new Blob([bytes],{type:mime}));
  }
  window.GAEMI_VOICE_EMBEDDED_ASSETS={
    image:asBlobUrl('','image/webp'),
    sample:asBlobUrl('','audio/mpeg')
  };
})();
